package com.enterprise.procurement.persistence.entity;
import com.baomidou.mybatisplus.annotation.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@TableName("purchase_order") public class PurchaseOrderEntity { @TableId(type=IdType.AUTO) private Long id; private String orderNo; private Long requestId; private Long supplierId; private BigDecimal totalAmount; private String status; private Integer version; private LocalDateTime createdAt; private LocalDateTime updatedAt; public Long getId(){return id;} public void setId(Long v){id=v;} public String getOrderNo(){return orderNo;} public void setOrderNo(String v){orderNo=v;} public Long getRequestId(){return requestId;} public void setRequestId(Long v){requestId=v;} public Long getSupplierId(){return supplierId;} public void setSupplierId(Long v){supplierId=v;} public BigDecimal getTotalAmount(){return totalAmount;} public void setTotalAmount(BigDecimal v){totalAmount=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public Integer getVersion(){return version;} public void setVersion(Integer v){version=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;} public LocalDateTime getUpdatedAt(){return updatedAt;} public void setUpdatedAt(LocalDateTime v){updatedAt=v;} }
